// k-nucleotide: read the THIRD sequence from FASTA on stdin,
// report 1-mer/2-mer frequencies and counts of specific fragments.

#include <cstdio>
#include <cstdint>
#include <cctype>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
#include <unordered_map>
#include <algorithm>
using namespace std;

static inline int code(char c) {
    switch (c) {
        case 'A': return 0;
        case 'C': return 1;
        case 'G': return 2;
        case 'T': return 3;
    }
    return -1;
}

static inline char baseChar(int c) {
    static const char tbl[4] = {'A', 'C', 'G', 'T'};
    return tbl[c];
}

int main(int argc, char **argv) {
    // N is given as argv[1] per the harness contract; not needed by this benchmark.
    if (argc > 1) {
        long n = strtol(argv[1], nullptr, 10);
        (void)n;
    }

    // Read all of stdin.
    string data;
    {
        char buf[1 << 16];
        size_t n;
        while ((n = fread(buf, 1, sizeof buf, stdin)) > 0)
            data.append(buf, n);
    }

    // Find the line starting with ">THREE".
    size_t pos = 0;
    bool found = false;
    while (pos < data.size()) {
        size_t eol = data.find('\n', pos);
        size_t lineEnd = (eol == string::npos) ? data.size() : eol;
        if (lineEnd > pos && data[pos] == '>' &&
            data.compare(pos, 5, "THREE") == 0) {
            found = true;
            pos = (eol == string::npos) ? data.size() : eol + 1;
            break;
        }
        pos = (eol == string::npos) ? data.size() : eol + 1;
    }

    // Collect sequence lines until the next header or EOF; uppercase, keep ACGT.
    string seq;
    seq.reserve(data.size() - pos);
    if (found) {
        while (pos < data.size()) {
            size_t eol = data.find('\n', pos);
            size_t lineEnd = (eol == string::npos) ? data.size() : eol;
            if (lineEnd > pos && data[pos] == '>')
                break;
            for (size_t i = pos; i < lineEnd; ++i) {
                char c = (char)toupper((unsigned char)data[i]);
                if (code(c) >= 0) seq.push_back(c);
            }
            if (eol == string::npos) break;
            pos = eol + 1;
        }
    }

    int L = (int)seq.size();

    auto countKmers = [&](int k) -> unordered_map<uint64_t, int> {
        unordered_map<uint64_t, int> m;
        m.reserve(64);
        if (L < k) return m;
        uint64_t mask = (1ull << (2 * k)) - 1ull;
        uint64_t key = 0;
        for (int i = 0; i < k; ++i) key = (key << 2) | (uint64_t)code(seq[i]);
        m[key]++;
        for (int i = k; i < L; ++i) {
            key = ((key << 2) | (uint64_t)code(seq[i])) & mask;
            m[key]++;
        }
        return m;
    };

    auto printFreqs = [&](int k) {
        auto m = countKmers(k);
        vector<pair<int, string> > v;
        v.reserve(m.size());
        for (auto &kv : m) {
            string s(k, 'A');
            uint64_t key = kv.first;
            for (int i = k - 1; i >= 0; --i) {
                s[i] = baseChar((int)(key & 3ull));
                key >>= 2;
            }
            v.push_back(make_pair(kv.second, s));
        }
        sort(v.begin(), v.end(), [](const pair<int, string> &a,
                                    const pair<int, string> &b) {
            if (a.first != b.first) return a.first > b.first;
            return a.second < b.second;
        });
        double total = (k == 1) ? (double)L : (double)(L - 1);
        for (auto &p : v) {
            printf("%s %.3f\n", p.second.c_str(),
                   total > 0 ? (p.first * 100.0 / total) : 0.0);
        }
    };

    auto countFragment = [&](const char *f) -> int {
        int k = (int)strlen(f);
        if (k > L) return 0;
        uint64_t key = 0;
        for (int i = 0; i < k; ++i) key = (key << 2) | (uint64_t)code(f[i]);
        uint64_t mask = (1ull << (2 * k)) - 1ull;
        uint64_t cur = 0;
        int cnt = 0;
        for (int i = 0; i < L; ++i) {
            cur = ((cur << 2) | (uint64_t)code(seq[i])) & mask;
            if (i >= k - 1 && cur == key) ++cnt;
        }
        return cnt;
    };

    printFreqs(1);
    printf("\n");
    printFreqs(2);
    printf("\n");

    const char *frags[] = {"GGT", "GGTA", "GGTATT",
                           "GGTATTTTAATT", "GGTATTTTAATTTATAGT"};
    for (const char *f : frags) {
        printf("%d\t%s\n", countFragment(f), f);
    }

    return 0;
}
```

