Looking at this problem:

- Input is FASTA on stdin (piped from a `fasta` generator), with `N` as `argv[1]` (only useful as a size hint).
- For each record: keep the `>` header line verbatim, reverse-complement the sequence bases.
- "Preserve line-wrapping": since the reversed sequence has the same length, keeping every newline at its exact original byte offset reproduces the original line-length pattern (for uniform 60-char wrapping this is identical to re-wrapping at the same width).

**Algorithm:** read all of stdin into one buffer, then for each sequence region do an in-place two-pointer reverse-complement: advance a front pointer and a back pointer inward, skipping `\n`/`\r` (which stay fixed in place), swapping each base pair with its complemented value, and complementing a lone middle base. This is O(n), single read, single write, and preserves headers/wrapping byte-for-byte. The 256-entry complement table covers the full IUPAC set (A↔T, C↔G, U→A, R↔Y, K↔M, B↔V, D↔H, S/W/N fixed), both upper and lower case, with identity default for anything else.

I verified the two-pointer logic on cases with short last lines, odd base counts, blank lines, and `\r\n` endings — newlines always remain at their original offsets and bases end up correctly reverse-complemented.

```cpp
#include <cstdio>
#include <cstdlib>
#include <cstddef>
#include <cstring>

namespace {

typedef unsigned char U8;

// IUPAC complement table; identity default (newlines / unknown codes pass through).
U8 g_comp[256];

void initComp() {
    for (int i = 0; i < 256; ++i) g_comp[i] = static_cast<U8>(i);
    g_comp['A'] = 'T'; g_comp['T'] = 'A';
    g_comp['C'] = 'G'; g_comp['G'] = 'C';
    g_comp['U'] = 'A';
    g_comp['R'] = 'Y'; g_comp['Y'] = 'R';
    g_comp['K'] = 'M'; g_comp['M'] = 'K';
    g_comp['B'] = 'V'; g_comp['V'] = 'B';
    g_comp['D'] = 'H'; g_comp['H'] = 'D';
    g_comp['S'] = 'S'; g_comp['W'] = 'W'; g_comp['N'] = 'N';
    g_comp['a'] = 't'; g_comp['t'] = 'a';
    g_comp['c'] = 'g'; g_comp['g'] = 'c';
    g_comp['u'] = 'a';
    g_comp['r'] = 'y'; g_comp['y'] = 'r';
    g_comp['k'] = 'm'; g_comp['m'] = 'k';
    g_comp['b'] = 'v'; g_comp['v'] = 'b';
    g_comp['d'] = 'h'; g_comp['h'] = 'd';
    g_comp['s'] = 's'; g_comp['w'] = 'w'; g_comp['n'] = 'n';
}

inline bool isSep(char c) { return c == '\n' || c == '\r'; }

// Reverse-complement buf[lo,hi) in place. Newline bytes keep their exact
// positions, so headers and line wrapping are preserved byte-for-byte.
void revcompRegion(char* buf, size_t lo, size_t hi) {
    size_t a = lo, b = hi;  // active window [a, b)
    while (a < b) {
        while (a < b && isSep(buf[a])) ++a;
        while (a < b && isSep(buf[b - 1])) --b;
        if (a >= b) break;
        if (a == b - 1) {  // odd base count: complement the middle base
            buf[a] = static_cast<char>(g_comp[static_cast<U8>(buf[a])]);
            break;
        }
        U8 x = g_comp[static_cast<U8>(buf[a])];
        U8 y = g_comp[static_cast<U8>(buf[b - 1])];
        buf[a] = static_cast<char>(y);
        buf[b - 1] = static_cast<char>(x);
        ++a;
        --b;
    }
}

}  // namespace

int main(int argc, char** argv) {
    initComp();

    // argv[1] carries N; used only as a capacity hint (data comes from stdin).
    unsigned long long hint = 0;
    if (argc > 1 && argv[1] != nullptr && argv[1][0] != '\0') {
        char* endp = nullptr;
        long long v = std::strtoll(argv[1], &endp, 10);
        if (endp != argv[1] && v > 0) hint = static_cast<unsigned long long>(v);
    }

    size_t cap = static_cast<size_t>(1) << 20;
    if (hint > 0) {
        const size_t maxBase = static_cast<size_t>(-1) / 4;
        size_t base = (hint > static_cast<unsigned long long>(maxBase))
                          ? maxBase
                          : static_cast<size_t>(hint);
        size_t need = base + base / 60 + 65536;  // bases + line breaks + slack
        if (need > cap) cap = need;
    }

    char* buf = static_cast<char*>(std::malloc(cap));
    if (buf == nullptr) {
        cap = static_cast<size_t>(1) << 20;
        buf = static_cast<char*>(std::malloc(cap));
        if (buf == nullptr) return 1;
    }

    size_t len = 0;
    for (;;) {
        if (len == cap) {
            if (cap > static_cast<size_t>(-1) / 2) break;
            const size_t ncap = cap << 1;
            char* nb = static_cast<char*>(std::realloc(buf, ncap));
            if (nb == nullptr) break;
            buf = nb;
            cap = ncap;
        }
        const size_t r = std::fread(buf + len, 1, cap - len, std::stdin);
        if (r == 0) break;
        len += r;
    }

    // Walk through FASTA records. Header lines are kept verbatim; the
    // sequence lines between headers are reverse-complemented in place,
    // which keeps every newline at its original offset (wrapping preserved).
    size_t i = 0;
    while (i < len) {
        if (buf[i] == '>') {
            void* nl = std::memchr(buf + i, '\n', len - i);
            i = nl ? static_cast<size_t>(static_cast<char*>(nl) - buf) + 1 : len;
        } else {
            const size_t start = i;
            size_t j = i;
            while (j < len && buf[j] != '>') {
                void* nl = std::memchr(buf + j, '\n', len - j);
                j = nl ? static_cast<size_t>(static_cast<char*>(nl) - buf) + 1 : len;
            }
            revcompRegion(buf, start, j);
            i = j;
        }
    }

    if (len > 0) std::fwrite(buf, 1, len, std::stdout);

    std::free(buf);
    return 0;
}
