#include <stdio.h>
#include <stdlib.h>
#include <math.h>

double A(int i, int j) {
    return 1.0/((i+j)*(i+j+1)/2 +i+1);
}

void MultiplyAv(double* v, double* Av, int n){
    for (int i=0; i<n; i++) {
        Av[i] = 0;
        for (int j=0; j<n; j++) Av[i] += A(i,j)*v[j];
    }
}

void MultiplyAtv(double* v, double* Atv, int n){
    for (int i=0; i<n; i++) {
        Atv[i] = 0;
        for (int j=0; j<n; j++) Atv[i] += A(j,i)*v[j];
    }
}

int main(int argc, char** argv) {
    int n = atoi(argv[1]);
    double u[n], vv[n], v[n];
    for (int i = 0; i < n; i++) u[i] = 1;
    for (int i=0; i<10; i++) {
        MultiplyAv(u, v, n);
        MultiplyAtv(v, u, n);
    }
    double vBv = 0, vv = 0;
    for (int i=0; i<n; i++) {
        vBv += u[i]*v[i];
        vv += v[i]*v[i];
    }
    printf("%0.9f\n", sqrt(vBv/vv));
