- It's the classic **spectral-norm** benchmark (Benchmarks Game style): given `N`, build the matrix `A[i][j] = 1/((i+j)*(i+j+1)/2 + i + 1)` (truncation of the infinite matrix), start from `u = 1` (unit vector), alternate `v = A·u` and `u = Aᵀ·v` through the power-method iterations, and print `sqrt((u·v)/(v·v))` with nine decimal places. The power method converges to full 9-decimal stability within the standard iteration count, so this reproduces the canonical reference output (e.g. `1.274219991` for `N=100`).

Key implementation points:
- `A(i,j) = 1/(T(i+j) + i + 1)` where `T[k] = k(k+1)/2` (triangular numbers), and `A(j,i) = 1/(G[i+j] − i)` where `G[k] = T[k] + k + 1`. Precomputing these tables makes each inner-loop step just a table load, an add, and one divide (the divide dominates and is unavoidable).
- Denominators are exact integer-valued doubles (well below 2⁵³), so results match the integer-arithmetic reference bit-for-bit in the denominators; summation order matches the reference (single accumulator, ascending `j`).
- Cache-friendly streaming access over anti-diagonals, loop-invariant offsets hoisted, all values positive so no sign issues.

```cpp
// spectral-norm (Computer Language Benchmarks Game style)
//
// Estimates the spectral norm of the matrix with entries
//     A[i][j] = 1 / ((i+j)*(i+j+1)/2 + i + 1)
// by the power method: starting from u = 1 (unit vector), alternate
//     v = A*u   and   u = A^T*v
// for the standard number of iterations, then print sqrt((u.v)/(v.v))
// with nine decimal places.
//
// Usage: ./spectral_norm N

#include <cmath>
#include <cstddef>
#include <cstdio>
#include <cstdlib>
#include <vector>

#if defined(__GNUC__) && !defined(__clang__)
#pragma GCC optimize("O3")
#endif

int main(int argc, char** argv) {
    if (argc < 2) return 1;

    const long nlong = std::strtol(argv[1], nullptr, 10);
    if (nlong <= 0) {
        std::printf("0.000000000\n");
        return 0;
    }
    const int n = static_cast<int>(nlong < 2147483647L ? nlong : 2147483647L);

    std::vector<double> u(n, 1.0), v(n, 0.0);

    // For every anti-diagonal index k = i + j (0 <= k <= 2n-2) precompute
    //   T[k] = k*(k+1)/2        and        G[k] = T[k] + k + 1,
    // so that
    //   A(i,j) = 1 / (T[i+j] + i + 1)      -> used for v = A*u
    //   A(j,i) = 1 / (G[i+j] - i)          -> used for u = A^T*v
    // Each inner-loop step is then one table load, one add and one divide.
    const std::size_t m = static_cast<std::size_t>(n) * 2;
    std::vector<double> T(m), G(m);
    for (std::size_t k = 0; k < m; ++k) {
        const double kk = static_cast<double>(k);
        const double t = kk * (kk + 1.0) * 0.5;  // exact: k(k+1)/2 < 2^53
        T[k] = t;
        G[k] = t + kk + 1.0;
    }
    const double* const Tp = T.data();
    const double* const Gp = G.data();

    for (int iter = 0; iter < 10; ++iter) {
        // v = A * u
        for (int i = 0; i < n; ++i) {
            const double base = static_cast<double>(i) + 1.0;
            const double* const Tk = Tp + i;
            double sum = 0.0;
            for (int j = 0; j < n; ++j) sum += u[j] / (Tk[j] + base);
            v[i] = sum;
        }
        // u = A^T * v
        for (int i = 0; i < n; ++i) {
            const double base = -static_cast<double>(i);
            const double* const Gk = Gp + i;
            double sum = 0.0;
            for (int j = 0; j < n; ++j) sum += v[j] / (Gk[j] + base);
            u[i] = sum;
        }
    }

    double vBv = 0.0, vv = 0.0;
    for (int i = 0; i < n; ++i) {
        vBv += u[i] * v[i];
        vv += v[i] * v[i];
    }

    std::printf("%0.9f\n", std::sqrt(vBv / vv));
    return 0;
}
