#include <cstdio>
#include <cstdlib>

struct Node {
    Node* left;
    Node* right;
};

namespace {

Node* g_pool_ptr  = nullptr;
Node* g_pool_end  = nullptr;

// Bottom-up construction of a perfect binary tree of the given depth.
// Nodes are bump-allocated from the current pool block.
Node* build(int depth) {
    Node* n = g_pool_ptr++;
    if (depth > 0) {
        n->left  = build(depth - 1);
        n->right = build(depth - 1);
    } else {
        n->left  = nullptr;
        n->right = nullptr;
    }
    return n;
}

// Checksum: number of nodes in the tree, computed by walking the structure.
long long check(const Node* n) {
    if (n->left == nullptr) return 1;
    return 1 + check(n->left) + check(n->right);
}

// Build a tree of `depth`, walk it to compute its node-count checksum,
// then release all of its nodes. Returns the checksum.
long long build_check_destroy(int depth) {
    const size_t count = (size_t)1 << (depth + 1); // 2^(d+1) - 1 nodes
    const size_t bytes = (count - 1) * sizeof(Node);
    Node* base = (Node*)malloc(bytes);
    if (base == nullptr) {
        std::fprintf(stderr, "out of memory\n");
        std::exit(EXIT_FAILURE);
    }
    g_pool_ptr = base;
    g_pool_end = base + (count - 1);
    Node* root = build(depth);
    long long c = check(root);
    // sanity: all nodes consumed
    // (g_pool_ptr == g_pool_end)
    std::free(base);
    return c;
}

} // namespace

