```cpp
// binary-trees benchmark:
// Allocate, walk (node-count checksum), and release many binary trees.

#include <cstdio>
#include <cstdlib>

#if defined(__GNUC__) && !defined(__clang__)
#pragma GCC optimize("O2")
#endif

struct Node {
    Node* left;
    Node* right;
};

// Bottom-up construction of a perfect binary tree of the given depth.
// Nodes are bump-allocated from a contiguous block obtained per tree.
static Node* build(Node*& pool, int depth) {
    Node* n = pool++;
    if (depth > 0) {
        n->left = build(pool, depth - 1);
        n->right = build(pool, depth - 1);
    } else {
        n->left = nullptr;
        n->right = nullptr;
    }
    return n;
}

// Node-count checksum: walk the tree and count its nodes.
static long long check(const Node* n) {
    if (n->left == nullptr) return 1;          // leaf
    return 1 + check(n->left) + check(n->right);
}

// Allocate a tree of the given depth, returning the root and base of its
// node block (for later release).
static Node* make_tree(int depth, Node*& base) {
    const size_t node_count = ((size_t)1 << (depth + 1)) - 1;
    base = (Node*)std::malloc(node_count * sizeof(Node));
    if (base == nullptr) {
        std::fprintf(stderr, "out of memory (depth %d)\n", depth);
        std::exit(EXIT_FAILURE);
    }
    Node* pool = base;
    return build(pool, depth);
}

// Build a tree, walk it to compute its checksum, then release it.
static long long build_check_release(int depth) {
    Node* base;
    Node* root = make_tree(depth, base);
    const long long c = check(root);
    std::free(base);
    return c;
}

int main(int argc, char** argv) {
    if (argc < 2) {
        std::fprintf(stderr, "usage: %s N\n", argv[0]);
        return EXIT_FAILURE;
    }

    char* end = nullptr;
    const long long n_in = std::strtoll(argv[1], &end, 10);
    if (end == argv[1] || n_in < 0 || n_in > 40) {
        std::fprintf(stderr, "invalid N\n");
        return EXIT_FAILURE;
    }
    const int N = static_cast<int>(n_in);

    // Stretch tree of depth N+1: build, check, release.
    const long long stretch_check = build_check_release(N + 1);
    std::printf("stretch tree of depth %d\t check: %lld\n", N + 1, stretch_check);

    // Long-lived tree of depth N: built now, released after the churn below.
    Node* long_base = nullptr;
    Node* long_root = make_tree(N, long_base);

    // Waves of short-lived trees of depths 4, 6, ..., N.
    for (int d = 4; d <= N; d += 2) {
        const long long iterations = 1LL << (N - d + 4);
        long long sum = 0;
        for (long long i = 0; i < iterations; ++i) {
            sum += build_check_release(d);
        }
        std::printf("%lld\t trees of depth %d\t check: %lld\n", iterations, d, sum);
    }

    std::printf("long lived tree of depth %d\t check: %lld\n", N, check(long_root));
    std::free(long_base);

    return 0;
}
```

