// Rows are packed MSB-first and padded to a byte boundary (P4 spec).

#include <cstdio>
#include <cstdlib>
#include <vector>
#include <thread>
#include <algorithm>

int main(int argc, char** argv) {
    if (argc < 2) {
        std::fprintf(stderr, "usage: %s N\n", argv[0]);
        return 1;
    }
    const long N = std::strtol(argv[1], nullptr, 10);
    if (N <= 0) {
        std::fprintf(stderr, "N must be a positive integer\n");
        return 1;
    }

    const size_t rowBytes = (size_t)((N + 7) / 8);  // rows padded to byte boundary
    const int maxIter = 50;

    // Render into bands so memory stays bounded even for very large N.
    const size_t targetBytes = 8u << 20;
    size_t bandRows = (size_t)N;
    if ((size_t)N * rowBytes > targetBytes) {
        bandRows = targetBytes / rowBytes;
        if (bandRows == 0) bandRows = 1;
    }
    std::vector<unsigned char> buf((size_t)bandRows * rowBytes, 0);

    unsigned hc = std::thread::hardware_concurrency();
    int maxThreads = hc ? (int)hc : 1;
    if (maxThreads > 64) maxThreads = 64;
    if (N < 128) maxThreads = 1;  // not worth spawning threads for tiny N

    auto worker = [&](long yBegin, long yEnd, long bandStart, unsigned char* bandBase) {
        for (long y = yBegin; y < yEnd; ++y) {
            const double ci = 2.0 * (double)y / (double)N - 1.0;
            unsigned char* row = bandBase + (size_t)(y - bandStart) * rowBytes;
            unsigned char bits = 0;
            int nbits = 0;
            size_t idx = 0;
            for (long x = 0; x < N; ++x) {
                const double cr = 2.0 * (double)x / (double)N - 1.5;
                double zx = 0.0, zy = 0.0;
                bool inside = true;
                for (int i = 0; i < maxIter; ++i) {
                    const double zx2 = zx * zx;
                    const double zy2 = zy * zy;
                    zy = 2.0 * zx * zy + ci;
                    zx = zx2 - zy2 + cr;
                    if (zx * zx + zy * zy > 4.0) {  // escaped radius 2
                        inside = false;
                        break;
                    }
                }
                bits = (unsigned char)((bits << 1) | (inside ? 1 : 0));
                if (++nbits == 8) {
                    row[idx++] = bits;
                    bits = 0;
                    nbits = 0;
                }
            }
            if (nbits != 0) {
                row[idx] = (unsigned char)(bits << (8 - nbits));
            }
        }
    };

    std::FILE* out = stdout;
    std::fprintf(out, "P4\n%ld %ld\n", N, N);

    for (long y0 = 0; y0 < N; y0 += (long)bandRows) {
        const long y1 = std::min(N, y0 + (long)bandRows);
        const long rows = y1 - y0;
        if (maxThreads <= 1) {
            worker(y0, y1, y0, buf.data());
        } else {
            const int nt = (int)std::min<long>(maxThreads, rows);
            const long chunk = (rows + nt - 1) / nt;
            std::vector<std::thread> pool;
            pool.reserve((size_t)nt);
            long doneUpTo = y0;
            try {
                for (int t = 0; t < nt; ++t) {
                    const long b = y0 + (long)t * chunk;
                    const long e = std::min(y1, b + chunk);
                    if (b >= e) break;
                    pool.emplace_back(worker, b, e, y0, buf.data());
                    doneUpTo = e;
                }
            } catch (...) {
                // Threads unavailable: remaining rows are done serially below.
            }
            for (auto& th : pool) th.join();
            if (doneUpTo < y1) worker(doneUpTo, y1, y0, buf.data());
        }
        std::fwrite(buf.data(), 1, (size_t)rows * rowBytes, out);
    }

    std::fflush(out);
    return 0;
}
